#include <bits/stdc++.h>
#define MAX_SIZE 7100
typedef long long ll;
#define INF 1000000000
using namespace std;

struct Maxflow {
    struct edge {
        int from, to;
        ll flow, capacity;
    };
    int s, t;
    vector<edge> edg;
    vector<int> g[MAX_SIZE];
    int dist[MAX_SIZE], visited[MAX_SIZE];
    int cur[MAX_SIZE];

    void init() {
        edg.clear();
        for (int i = 0; i < MAX_SIZE; ++i) g[i].clear();
    }

    void addedge(int from, int to, ll capacity) {
        edg.push_back({from, to, 0ll, capacity});
        edg.push_back({to, from, 0ll, 0ll});
        g[from].push_back((int)edg.size() - 2);
        g[to].push_back((int)edg.size() - 1);
    }

    bool bfs() {
        memset(visited, 0, sizeof(visited));
        memset(dist, 0, sizeof(dist));
        queue<int> q;
        q.push(s);
        visited[s] = 1;
        dist[s] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int i = 0; i < (int)g[v].size(); ++i) {
                edge &e = edg[g[v][i]];
                int nxt = e.to;
                if (!visited[nxt] && e.capacity > e.flow) {
                    dist[nxt] = dist[v] + 1;
                    q.push(nxt);
                    visited[nxt] = 1;
                }
            }
        }
        return visited[t];
    }

    ll dfs(int x, ll cp) {
        if (x == t || cp == 0) return cp;
        ll flow = 0, newflow;
        for (int &y = cur[x]; y < (int)g[x].size(); ++y) {
            edge &e = edg[g[x][y]];
            if (dist[x] + 1 == dist[e.to]) {
                ll minn = min(cp, e.capacity - e.flow);
                newflow = dfs(e.to, minn);
                if (newflow > 0) {
                    e.flow += newflow;
                    edg[g[x][y] ^ 1].flow -= newflow;
                    flow += newflow;
                    cp -= newflow;
                    if (cp == 0) break;
                }
            }
        }
        return flow;
    }

    ll Dinic() {
        ll flow = 0;
        while (bfs()) {
            memset(cur, 0, sizeof(cur));
            flow += dfs(s, INF);
        }
        return flow;
    }
};

Maxflow mf;
