import sys
from collections import deque

MAX_SIZE = 7100
INF = 1000000000

class Maxflow:
    def __init__(self):
        self.s = 0
        self.t = MAX_SIZE - 2
        self.edg = []  # each edge: [from, to, flow, capacity]
        self.g = [[] for _ in range(MAX_SIZE)]
        self.dist = [0] * MAX_SIZE
        self.visited = [0] * MAX_SIZE
        self.cur = [0] * MAX_SIZE

    def init(self):
        self.edg.clear()
        for i in range(MAX_SIZE):
            self.g[i].clear()

    def addedge(self, from_, to, capacity):
        self.edg.append([from_, to, 0, capacity])
        self.edg.append([to, from_, 0, 0])
        self.g[from_].append(len(self.edg) - 2)
        self.g[to].append(len(self.edg) - 1)

    def bfs(self):
        self.visited = [0] * MAX_SIZE
        self.dist = [0] * MAX_SIZE
        q = deque()
        q.append(self.s)
        self.visited[self.s] = 1
        self.dist[self.s] = 0
        while q:
            v = q.popleft()
            for i in self.g[v]:
                e = self.edg[i]
                nxt = e[1]
                if not self.visited[nxt] and e[3] > e[2]:
                    self.dist[nxt] = self.dist[v] + 1
                    q.append(nxt)
                    self.visited[nxt] = 1
        return self.visited[self.t]

    def dfs(self, x, cp):
        if x == self.t or cp == 0:
            return cp
        flow = 0
        while self.cur[x] < len(self.g[x]):
            idx = self.g[x][self.cur[x]]
            e = self.edg[idx]
            if self.dist[x] + 1 == self.dist[e[1]]:
                minn = min(cp, e[3] - e[2])
                newflow = self.dfs(e[1], minn)
                if newflow > 0:
                    e[2] += newflow
                    self.edg[idx ^ 1][2] -= newflow
                    flow += newflow
                    cp -= newflow
                    if cp == 0:
                        break
            self.cur[x] += 1
        return flow

    def Dinic(self):
        flow = 0
        while self.bfs():
            self.cur = [0] * MAX_SIZE
            flow += self.dfs(self.s, INF)
        return flow

def index(level, x, y):
    return level * n * n + (x - 1) * n + y

def BFS(x, y):
    global dist, visited
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            dist[i][j] = 111
    dist[x][y] = 0
    q = deque()
    q.append((x, y, 0))
    dx = [1, 0, 0, -1]
    dy = [0, 1, -1, 0]
    while q:
        cx, cy, d = q.popleft()
        if visited[cx][cy]:
            continue
        visited[cx][cy] = True
        dist[cx][cy] = d
        for i in range(4):
            tx = cx + dx[i]
            ty = cy + dy[i]
            if 1 <= tx <= n and 1 <= ty <= n and not visited[tx][ty] and g1[tx][ty] != 'Y':
                q.append((tx, ty, d + 1))

def main():
    global n, g1, g2, dist, visited
    data = sys.stdin.read().split()
    it = iter(data)
    n = int(next(it))
    t = int(next(it))
    # read g1 (n lines)
    g1 = [[''] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        line = next(it)
        for j in range(1, n + 1):
            g1[i][j] = line[j - 1]
    # read g2 (n lines)
    g2 = [[''] * (n + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        line = next(it)
        for j in range(1, n + 1):
            g2[i][j] = line[j - 1]

    # find start 'Z'
    sx = sy = 0
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if g1[i][j] == 'Z':
                sx, sy = i, j
                break
        if sx:
            break

    # BFS distances
    visited = [[False] * (n + 1) for _ in range(n + 1)]
    dist = [[0] * (n + 1) for _ in range(n + 1)]
    BFS(sx, sy)

    mf = Maxflow()
    mf.s = 0
    mf.t = MAX_SIZE - 2

    # tgt array: maps node index to sink node
    tgt = [0] * (n * n + 1)
    for i in range(1, n * n + 1):
        tgt[i] = MAX_SIZE - 3 - (n * n - i)

    # source and sink edges for level 0
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if '0' <= g1[i][j] <= '9':
                mf.addedge(mf.s, index(0, i, j), ord(g1[i][j]) - ord('0'))
            if '0' <= g2[i][j] <= '9':
                mf.addedge(tgt[index(0, i, j)], mf.t, ord(g2[i][j]) - ord('0'))
            mf.addedge(index(0, i, j), tgt[index(0, i, j)], INF)

    dx = [1, 0, 0, -1]
    dy = [0, 1, -1, 0]
    for time in range(1, t + 1):
        for i in range(1, n + 1):
            for j in range(1, n + 1):
                if g1[i][j] == 'Y' or g1[i][j] == 'Z':
                    continue
                for d in range(4):
                    tx = i + dx[d]
                    ty = j + dy[d]
                    if 1 <= tx <= n and 1 <= ty <= n and g1[tx][ty] != 'Y' and g1[tx][ty] != 'Z':
                        if dist[i][j] >= time and dist[tx][ty] >= time:
                            mf.addedge(index(time - 1, tx, ty), index(time, i, j), INF)
                mf.addedge(index(time, i, j), tgt[index(0, i, j)], INF)

    result = mf.Dinic()
    print(result)

if __name__ == "__main__":
    sys.setrecursionlimit(10000)
    main()
